// The `match stringify!($i) { .. }` ending every setter (src/tools/rustfmt/src/config/config_type.rs:122, :152) and the second `match key { .. }` of
// `override_value` (:352): the same match in every expansion. PORT: one module-local function, not a copy per option and setter.
function __set_dependent_options(config: Config, key: string): void {
  switch (key) {
    case "max_width":
    case "use_small_heuristics":
    case "fn_call_width":
    case "single_line_if_else_max_width":
    case "single_line_let_else_max_width":
    case "attr_fn_like_width":
    case "struct_lit_width":
    case "struct_variant_width":
    case "array_width":
    case "chain_width":
      config.set_heuristics();
      break;
    case "merge_imports":
      config.set_merge_imports();
      break;
    case "fn_args_layout":
      config.set_fn_args_layout();
      break;
    case "hide_parse_errors":
      config.set_hide_parse_errors();
      break;
    case "version":
      config.set_version();
      break;
    default:
      break;
  }
}

// ---- module-local helpers (std pieces src/std does not have yet) ----
/** `isize::MAX` as a usize (only compared with config widths, far below 2^53). */
const ISIZE_MAX = 2 ** 63 - 1;
/** `usize::saturating_add_signed` over the port's `usize::MAX` (tools/codegen/create_config.ts `usizeSaturatingAddSigned`). */
function usize_saturating_add_signed(value: number, delta: number): number {
  if (value >= USIZE_MAX) return USIZE_MAX;
  const r = value + delta;
  return r <= 0 ? 0 : r >= USIZE_MAX ? USIZE_MAX : r;
}
/** `dyn std::io::Write` as `print_docs` uses it: `writeln!(out, ..)` is `out.write_fmt(<text>)` (std::io::Write::write_fmt). */
export interface Write {
  write_fmt(text: string): IoResult<null>;
}
/** `impl FromStr for bool` (core::str::traits): only `true` and `false`. */
function __bool_from_str(s: string): Result<boolean, null> {
  if (s === "true") return Ok(true);
  if (s === "false") return Ok(false);
  return Err(null);
}
/** `#[derive(Debug)] pub struct ParseBoolError;` (core::str::error) */
const __debug_ParseBoolError = (_e: null): string => "ParseBoolError";
/** `#[derive(Debug)] pub struct ParseIntError { kind: IntErrorKind }` (core::num::error) */
const __debug_ParseIntError = (e: ParseIntError, f: Fmt): string => debug_struct(f, "ParseIntError", [["kind", e.kind]]);
/** `Infallible` has no values. */
const __debug_Infallible = (_e: never): string => unreachable();

/** `__value == name.as_bytes()` (the `b"name"` arms of serde_derive's field visitors). */
function __bytes_eq(value: Uint8Array, name: string): boolean {
  const b = new TextEncoder().encode(name);
  if (value.length !== b.length) return false;
  for (let i = 0; i < b.length; i++) if (value[i] !== b[i]) return false;
  return true;
}
